def standardize_readings(sensor_readings, new_min, new_max):
    if not sensor_readings:
        return []  # Return an empty list if input is empty

    readings_min = min(sensor_readings)
    readings_max = max(sensor_readings)

    if readings_min == readings_max:
        # If all values are the same, return a list with the scaled value
        scaled_value = new_min
        return [scaled_value] * len(sensor_readings)

    scaled_readings = []
    for reading in sensor_readings:
        scaled_value = (reading - readings_min) / (readings_max - readings_min) * (new_max - new_min) + new_min
        scaled_readings.append(scaled_value)

    return scaled_readings

