def analyze_movement_patterns(gps_data):
    from datetime import datetime
    from math import radians, cos, sin, asin, sqrt

    def haversine_distance(lat1, lon1, lat2, lon2):
        """
        Calculate the great circle distance between two points
        on the earth's surface (specified in decimal degrees)
        """
        # Convert decimal degrees to radians
        lon1, lat1, lon2, lat2 = map(radians, [lon1, lat1, lon2, lat2])

        # Haversine formula
        dlon = lon2 - lon1
        dlat = lat2 - lat1
        a = sin(dlat/2)**2 + cos(lat1) * cos(lat2) * sin(dlon/2)**2
        c = 2 * asin(sqrt(a))
        r = 6371  # Radius of earth in kilometers
        return c * r

    # Sort the data by timestamp
    sorted_data = sorted(gps_data, key=lambda x: datetime.strptime(x[1], "%Y-%m-%d %H:%M:%S"))

    animal_distances = {}

    for i in range(len(sorted_data) - 1):
        animal_id, timestamp, location = sorted_data[i]
        next_animal_id, next_timestamp, next_location = sorted_data[i + 1]

        if animal_id == next_animal_id:
            distance = haversine_distance(location[0], location[1], next_location[0], next_location[1])
            if animal_id in animal_distances:
                animal_distances[animal_id].append(distance)
            else:
                animal_distances[animal_id] = [distance]

    longest_avg_distance = []
    shortest_avg_distance = []

    for animal_id, distances in animal_distances.items():
        avg_distance = sum(distances) / len(distances)
        if not longest_avg_distance or avg_distance >= max(animal_distances[id] for id in longest_avg_distance):
            if avg_distance > max(animal_distances[id] for id in longest_avg_distance):
                longest_avg_distance = [animal_id]
            else:
                longest_avg_distance.append(animal_id)
        if not shortest_avg_distance or avg_distance <= min(animal_distances[id] for id in shortest_avg_distance):
            if avg_distance < min(animal_distances[id] for id in shortest_avg_distance):
                shortest_avg_distance = [animal_id]
            else:
                shortest_avg_distance.append(animal_id)

    return (longest_avg_distance, shortest_avg_distance)

