def calculate_total_road_length(landmarks):
    import math

    def distance(a, b):
        return math.sqrt((a[0] - b[0])**2 + (a[1] - b[1])**2)

    n = len(landmarks)
    if n < 2:
        return 0.0

    total_length = 0
    for i in range(n):
        min_dist = float('inf')
        for j in range(i + 1, n):
            dist = distance(landmarks[i], landmarks[j])
            if dist < min_dist:
                min_dist = dist
        total_length += min_dist

    return round(total_length, 2)

def godzilla_path(city):
    if not city:
        return 0

    rows, cols = len(city), len(city[0])
    destroyed = 0
    row, col = 0, 0
    direction = 0  # 0: right, 1: down, 2: left, 3: up

    while True:
        if row < 0 or row >= rows or col < 0 or col >= cols:
            break

        if city[row][col] == 'B':
            destroyed += 1
            city[row][col] = '.'

        if direction == 0:  # right
            col += 1
            if col == cols or (row < rows - 1 and city[row + 1][col] == 'B'):
                direction = 1
        elif direction == 1:  # down
            row += 1
            if row == rows or (col > 0 and city[row][col - 1] == 'B'):
                direction = 2
        elif direction == 2:  # left
            col -= 1
            if col < 0 or (row > 0 and city[row - 1][col] == 'B'):
                direction = 3
        elif direction == 3:  # up
            row -= 1
            if row < 0 or (col < cols - 1 and city[row][col + 1] == 'B'):
                direction = 0

    return destroyed

