def calculate_avg_sales_growth(sales_data):
    if len(sales_data) < 2:
        return 0.0

    growth_rates = []
    for i in range(1, len(sales_data)):
        previous_month_sales = sales_data[i-1]
        current_month_sales = sales_data[i]
        if previous_month_sales == 0:
            continue
        growth_rate = (current_month_sales - previous_month_sales) / previous_month_sales * 100
        growth_rates.append(growth_rate)

    if not growth_rates:
        return 0.0

    avg_growth_rate = sum(growth_rates) / len(growth_rates)
    return round(avg_growth_rate, 2)

